#include <stdio.h>
#include <stdlib.h>

static int read_int(void) {
    int ch = getchar_unlocked();
    while (ch != EOF && ch <= ' ') ch = getchar_unlocked();

    int sign = 1;
    if (ch == '-') {
        sign = -1;
        ch = getchar_unlocked();
    }

    int value = 0;
    while (ch >= '0' && ch <= '9') {
        value = value * 10 + (ch - '0');
        ch = getchar_unlocked();
    }
    return sign * value;
}

int main(void) {
    int L = read_int();
    int C = read_int();

    int *prev = malloc((size_t)C * sizeof(int));
    int *curr = malloc((size_t)C * sizeof(int));
    int K = C - 1;
    int *height = calloc((size_t)K, sizeof(int));
    int *stack = malloc((size_t)(K + 1) * sizeof(int));

    for (int j = 0; j < C; ++j) {
        prev[j] = read_int();
    }

    long long answer = L > C ? L : C;

    for (int i = 1; i < L; ++i) {
        for (int j = 0; j < C; ++j) {
            curr[j] = read_int();
        }

        for (int j = 0; j < K; ++j) {
            int left_diff = curr[j] - prev[j];
            int right_diff = curr[j + 1] - prev[j + 1];

            if (left_diff < right_diff)
                height[j] = 0;
            else
                ++height[j];
        }

        int top = -1;
        for (int j = 0; j <= K; ++j) {
            int current_height = (j == K) ? 0 : height[j];

            while (top >= 0 && height[stack[top]] > current_height) {
                int h = height[stack[top--]];
                int left = (top < 0) ? 0 : stack[top] + 1;
                int width = j - left;
                long long area = (long long)(h + 1) * (width + 1);
                if (area > answer) answer = area;
            }

            stack[++top] = j;
        }

        int *tmp = prev;
        prev = curr;
        curr = tmp;
    }

    printf("%lld\n", answer);

    free(prev);
    free(curr);
    free(height);
    free(stack);
    return 0;
}
